#!/usr/bin/env python3
from pathlib import Path
import sys,json,zlib,base64,hashlib
if len(sys.argv)!=2: raise SystemExit("usage: patch-shishalove-1.1.78-products-recent-grid-candidate.py <plugin-dir>")
root=Path(sys.argv[1])
payload=json.loads(zlib.decompress(base64.b64decode("")))
for rel,spec in payload.items():
 p=root/rel; data=p.read_bytes()
 if hashlib.sha256(data).hexdigest()!=spec["sha"]: raise SystemExit("unexpected one-shot diagnostic 1.1.78 baseline: "+rel)
 lines=data.decode("utf-8").splitlines(keepends=True)
 for i1,i2,text in reversed(spec["ops"]): lines[i1:i2]=text.splitlines(keepends=True)
 p.write_text("".join(lines),encoding="utf-8")
for rel,sha in {"assets/customer.js":"bc3d794decaae688ae97ae3a19ff520b9fc71cefa8c332f8aab0d7372818b5d4"}.items():
 if hashlib.sha256((root/rel).read_bytes()).hexdigest()!=sha: raise SystemExit("preservation lock failed: "+rel)
p=(root/"shishalove-app-bridge.php").read_text();m=(root/"assets/merchant.js").read_text();c=(root/"assets/bridge.css").read_text()
for token in ["Version: 1.1.78","productViewPref","data-product-view","slm-product-grid","date_created","recent-grid-v1"]:
 if token not in p+m+c: raise SystemExit("missing recent/grid candidate token: "+token)
if "Version: 1.1.79" in p: raise SystemExit("version bump forbidden")
print("Bridge 1.1.78 Products recent-first + 3-column grid candidate applied; version intentionally unchanged")
